  { id: "ch", land: "CH", label: "Schweiz", sub: "Mittelland", ertrag: 1050 },
];

export const regionById = (id) => REGIONEN.find((r) => r.id === id) || REGIONEN[3];

/** Mehrertrag/Minderertrag nach Anlagenbauart gegenüber fester Süd-Aufständerung */
